package app.loveu;
import android.app.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;
final class PeriodView extends LinearLayout {
 final MainActivity a;boolean partner;final String key;
 PeriodView(MainActivity activity){super(activity);a=activity;setOrientation(VERTICAL);partner="男".equals(a.settings().optString("profileGender"));key=partner?"menstrualPartner":"menstrualSelf";render();}
 JSONArray data(){JSONArray values=a.root.optJSONArray(key);return values==null?new JSONArray():values;}
 List<PeriodAnalysis.Entry> entries(JSONArray values,String skip)throws Exception{List<PeriodAnalysis.Entry> out=new ArrayList<>();for(int i=0;i<values.length();i++){JSONObject e=values.getJSONObject(i);if(!e.optString("id").equals(skip))out.add(new PeriodAnalysis.Entry(e.getString("start"),e.isNull("end")?null:e.getString("end")));}return out;}
 void render(){removeAllViews();LinearLayout hero=Ui.card(a);hero.setBackground(Ui.hero(a));hero.addView(a.text(partner?"关怀大姨妈":"记录大姨妈",23,a.ink));hero.addView(a.text(partner?"帮她记住每一个周期":"照顾自己的每一个周期",12,a.muted));addView(hero);a.attempt(()->{JSONArray all=data();JSONObject active=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).isNull("end"))active=all.getJSONObject(i);final JSONObject ongoing=active;if(active==null)addView(a.button("今天开始",()->saveStart()));else{addView(a.text("进行中 · 第 "+(java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(active.getString("start")),LocalDate.now())+1)+" 天",18,a.berry));addView(a.button("今天结束",()->a.attempt(()->{JSONObject update=new JSONObject(ongoing.toString());update.put("end",LocalDate.now().toString());save(update);render();})));}addView(PeriodForecastCard.create(a,partner));addView(a.button("分享所有经期记录给爱人",()->BulkShareDialog.show(a,"period")));addView(a.button("补记经期",()->edit(null)));long remind=a.settings().optLong(key+"Reminder",0);addView(a.button(remind>System.currentTimeMillis()?"关怀提醒 · "+java.time.Instant.ofEpochMilli(remind).atZone(ZoneId.systemDefault()).toLocalDate():"设置关怀提醒",()->reminder()));if(remind>System.currentTimeMillis())addView(a.button("取消关怀提醒",()->a.attempt(()->{a.settings().remove(key+"Reminder");a.vault.write(a.root);PeriodReminder.schedule(a,key,0);render();})));LinearLayout analysis=Ui.card(a);analysis.addView(a.text("经期分析",17,a.ink));analysis.addView(a.text(PeriodAnalysis.summary(PeriodRecords.entries(a.root,partner),LocalDate.now()),14,a.ink));analysis.addView(a.text("预计范围仅依据已有记录，不用于避孕判断",10,a.muted));addView(analysis);TreeMap<String,Integer> lengths=new TreeMap<>();for(int i=0;i<all.length();i++){JSONObject e=all.getJSONObject(i);if(!e.isNull("end"))lengths.put(e.getString("start"),(int)java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(e.getString("start")),LocalDate.parse(e.getString("end")))+1);}if(!lengths.isEmpty()){LinearLayout chart=Ui.card(a);chart.addView(a.text("经期天数趋势",17,a.ink));HorizontalScrollView sc=new HorizontalScrollView(a);sc.setHorizontalScrollBarEnabled(false);sc.addView(new InsightsView.Bars(a,lengths,false,false),new android.view.ViewGroup.LayoutParams(Math.max(a.dp(270),a.dp(lengths.size()*80)),a.dp(180)));chart.addView(sc);addView(chart);}addView(a.text("经期历史",17,a.ink));for(int i=all.length()-1;i>=0;i--){JSONObject e=all.getJSONObject(i);LinearLayout card=Ui.card(a);card.addView(a.text(e.getString("start")+" ～ "+(e.isNull("end")?"进行中":e.getString("end")),15,a.ink));String info=e.optString("flow","")+"  "+e.optString("pain","")+"  "+Language.raw(e.optString("symptoms",""));if(!info.trim().isEmpty())card.addView(a.text(info.trim(),12,a.muted));card.addView(a.button("编辑",()->edit(e)));card.addView(a.button("分享这段经期给伴侣",()->CoupleView.preview(a,e,"period",partner)));card.addView(a.button("删除经期",()->a.confirm("删除这段经期记录？",()->a.attempt(()->{delete(e.getString("id"));render();}))));addView(card);}});}
 void delete(String id)throws Exception{if(a.locked)throw new IllegalStateException("请先解锁");JSONObject latest=a.vault.read();JSONArray all=latest.optJSONArray(key),keep=new JSONArray();if(all!=null)for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);if(!id.equals(item.getString("id")))keep.put(item);}latest.put(key,keep);a.vault.write(latest);a.root=latest;}
 void saveStart(){a.attempt(()->{save(new JSONObject().put("id",UUID.randomUUID().toString()).put("start",LocalDate.now().toString()).put("end",JSONObject.NULL));render();});}
 void save(JSONObject value)throws Exception{if(a.locked)throw new IllegalStateException("请先解锁");JSONObject latest=a.vault.read();JSONArray all=latest.optJSONArray(key);if(all==null)all=new JSONArray();PeriodAnalysis.validate(new PeriodAnalysis.Entry(value.getString("start"),value.isNull("end")?null:value.getString("end")),entries(all,value.getString("id")),LocalDate.now());JSONArray next=new JSONArray();boolean replaced=false;for(int i=0;i<all.length();i++){JSONObject old=all.getJSONObject(i);if(old.getString("id").equals(value.getString("id"))){next.put(value);replaced=true;}else next.put(old);}if(!replaced)next.put(value);latest.put(key,next);a.vault.write(latest);a.root=latest;}
 Spinner choose(LinearLayout box,String title,String[] options,String selected){box.addView(a.text(title,13,a.muted));Spinner spin=new Spinner(a);spin.setAdapter(new LanguageAdapter(a,options));for(int i=0;i<options.length;i++)if(options[i].equals(selected))spin.setSelection(i);box.addView(spin);return spin;}
 void reminder(){if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},73);Toast.makeText(a,Language.ui("允许通知后，再点设置提醒"),Toast.LENGTH_SHORT).show();return;}LocalDate now=LocalDate.now();DatePickerDialog d=new DatePickerDialog(a,(view,y,m,day)->a.attempt(()->{long time=LocalDate.of(y,m+1,day).atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();if(time<=System.currentTimeMillis())throw new IllegalArgumentException("请选择未来日期，提醒时间为上午9点");PeriodReminder.schedule(a,key,time);a.settings().put(key+"Reminder",time);a.vault.write(a.root);render();}),now.getYear(),now.getMonthValue()-1,now.getDayOfMonth());d.getDatePicker().setMinDate(System.currentTimeMillis());a.dialogs.add(d);d.show();}
 void pick(EditText target,boolean canClear){LocalDate date;try{date=LocalDate.parse(target.getText().toString());}catch(Exception ignored){date=LocalDate.now();}DatePickerDialog dialog=new DatePickerDialog(a,(view,y,m,d)->target.setText(LocalDate.of(y,m+1,d).toString()),date.getYear(),date.getMonthValue()-1,date.getDayOfMonth());dialog.getDatePicker().setMaxDate(System.currentTimeMillis());if(canClear)dialog.setButton(android.content.DialogInterface.BUTTON_NEUTRAL,Language.ui("设为进行中"),(d,w)->target.setText(""));a.dialogs.add(dialog);dialog.show();}
 void edit(JSONObject original){LinearLayout box=a.column();box.setPadding(a.dp(16),a.dp(8),a.dp(16),a.dp(8));EditText start=a.field(box,"开始日期 YYYY-MM-DD",original==null?LocalDate.now().toString():original.optString("start"),1),end=a.field(box,"结束日期，留空表示进行中",original==null||original.isNull("end")?"":original.optString("end"),1);start.setFocusable(false);end.setFocusable(false);start.setOnClickListener(v->pick(start,false));end.setOnClickListener(v->pick(end,true));Spinner flow=choose(box,"经量",new String[]{"未填写","少","中","多"},original==null?"":original.optString("flow")),pain=choose(box,"疼痛",new String[]{"未填写","无","轻度","中度","重度"},original==null?"":original.optString("pain"));EditText symptoms=a.field(box,"症状 / 关怀备注（可不填）",original==null?"":original.optString("symptoms"),1);ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog dialog=new LanguageDialog(a).setTitle("经期记录").setView(scroll).setNegativeButton("取消",null).setPositiveButton("保存",null).create();a.dialogs.add(dialog);dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->a.attempt(()->{JSONObject value=original==null?new JSONObject().put("id",UUID.randomUUID().toString()):new JSONObject(original.toString());String last=end.getText().toString().trim();value.put("start",start.getText().toString().trim()).put("end",last.isEmpty()?JSONObject.NULL:last).put("flow",flow.getSelectedItem().toString()).put("pain",pain.getSelectedItem().toString()).put("symptoms",symptoms.getText().toString().trim());save(value);dialog.dismiss();render();})));dialog.show();}
}

